mapper.select:
SELECT T0.BOOKSET_ID AS FINPRODID, T0.BOOKSET_NAME AS FINPRODNAME, T0.ACCT_MODE AS FINPRODTYPE, t2.val_date AS VALDATE, IFNULL(T2.BUILD_STATUS, '0') AS BUILDSTATUS, '' AS ERRORINFO, T2.ERROR_TYPE AS ERRORTYPE from BOK_BOOKSET T0 inner JOIN BOK_VALBAL_TABLE_LOG T2 ON T0.ACCT_SUBJECT_ID = T2.FINPROD_ID AND T2.VAL_BAL_FLAG = #{fileType} where 1 = 1
AND T0.BOOKSET_ID in
#{prdId}
AND T0.ACCT_MODE in
#{prodType}
and t2.val_date >= #{valDateBegin,jdbcType=DATE}
and t2.val_date <= #{valDateEnd,jdbcType=DATE}
AND IFNULL(T2.BUILD_STATUS, '0') in
#{buildStatus}
order by t2.VAL_DATE desc

select prd.finprod_id,IFNULL(prd.finprod_abbr,prd.finprod_name) finprod_abbr from fin_product prd 
	where 1=1

	AND prd.FINPROD_TYPE = #{finprodType}

SELECT COUNT(*) FROM ( SELECT B.VAL_DATE AS valDate,B.FINPROD_ID AS finprodId,B.FINPROD_NAME AS finprodName, SUM(B.CAPITAL�? AS CAPITAL,SUM(B.ASSET_VALUE) AS assetValue,SUM(B.NET_UNIT_VALUE�? AS netUnitValue,
SUM(B.TAOTALNETVALUE) AS TAOTALNETVALUE,SUM(B.SEVENDAYRATE) AS SEVENDAYRATE,SUM(B.PAYPROFIT) AS PAYPROFIT FROM ( SELECT A.VAL_DATE AS VAL_DATE,A.FINPROD_ID AS FINPROD_ID,A.FINPROD_NAME AS FINPROD_NAME, CASE WHEN A.DETAIL_DIST = '01' AND SUBJECT_NO = '22320101' THEN (case when A.BAL_FLAG = 'C' then 1 else -1 end) *A.COST ELSE 0 END AS PAYPROFIT, CASE WHEN A.DETAIL_DIST = '02' THEN A.COST ELSE 0 END AS CAPITAL, (case when A.PROFIT_TYPE = '01' then (case when A.DETAIL_DIST = '07' then A.COST else 0 end) when A.PROFIT_TYPE = '03' then (case when A.DETAIL_DIST = '28' then CAST( A.SUBJECT_NAME ) else 0 end) else 0 end) ASSET_VALUE,
(case when A.PROFIT_TYPE = '01' then (case when A.DETAIL_DIST = '08' then CAST( A.SUBJECT_NAME ) else 0 end) when A.PROFIT_TYPE = '03' then (case when A.DETAIL_DIST = '29' then CAST( A.SUBJECT_NAME ) else 0 end) else 0 end) NET_UNIT_VALUE, CASE WHEN A.DETAIL_DIST = '17' THEN CAST(A.SUBJECT_NAME) ELSE 0 END AS TAOTALNETVALUE, CASE WHEN A.DETAIL_DIST = '33' THEN CAST(A.SUBJECT_NAME) ELSE 0 END AS SEVENDAYRATE FROM ( SELECT BVD.VAL_DATE AS VAL_DATE,BVD.COST AS COST,BVD.DETAIL_DIST AS DETAIL_DIST,BVD.SUBJECT_NO,BVD.SUBJECT_NAME, BB.ACCT_SUBJECT_ID AS FINPROD_ID,BB.BOOKSET_NAME AS FINPROD_NAME ,BB.ACCT_MODE PROFIT_TYPE,BVD.BAL_FLAG FROM BOK_VAL_TABLE_DATA BVD JOIN BOK_BOOKSET BB ON BVD.BOOKSET_ID = BB.BOOKSET_ID
WHERE 1=1
AND BVD.VAL_DATE >= #{valDateBegin,jdbcType=DATE}
AND BVD.VAL_DATE <= #{valDateEnd,jdbcType=DATE}
AND BB.ACCT_SUBJECT_ID = #{prodId}
AND BVD.DETAIL_DIST IN ('01','02','07','08','17','28','29','33') ) A ) B GROUP BY B.VAL_DATE,B.FINPROD_ID,B.FINPROD_NAME )
